// @ts-check
import { defineConfig, passthroughImageService } from "astro/config";
import starlight from "@astrojs/starlight";
import sitemap from "@astrojs/sitemap";
import starlightLinksValidator from "starlight-links-validator";
import starlightPageActions from "starlight-page-actions";
import starlightLlmsTxt from "@hey-api/starlight-llms-txt";
import { onceHubSidebar, scheduleOnceSidebar } from "./src/sidebarConfig.mjs";
import { readFileSync } from "fs";
import { join } from "path";

import tailwindcss from "@tailwindcss/vite";

// Load per-page lastmod cache (generated by scripts/generate-sitemap-lastmod-cache.mjs)
let sitemapCache = {};
try {
  sitemapCache = JSON.parse(
    readFileSync(join(process.cwd(), "sitemap-lastmod-cache.json"), "utf-8"),
  );
} catch {
  // Cache file may not exist during dev or initial builds — that's okay
}

// https://astro.build/config
export default defineConfig({
  site: "https://help.staticso2.com",
  image: {
    service: passthroughImageService(),
  },
  integrations: [
    sitemap({
      serialize(item) {
        try {
          const url = new URL(item.url);
          const cachedDate = sitemapCache[url.pathname];
          if (cachedDate) {
            item.lastmod = cachedDate;
          }
        } catch {
          // Ignore malformed URLs
        }
        return item;
      },
    }),
    starlight({
      title: "Help Center",
      logo: {
        src: "./src/assets/logo.svg",
        alt: "OnceHub Logo",
      },
      components: {
        Hero: "./src/components/Hero.astro",
        Sidebar: "./src/components/Sidebar.astro",
        SocialIcons: "./src/components/SocialIcons.astro",
        PageTitle: "./src/components/PageTitle.astro",
        SiteTitle: "./src/components/SiteTitle.astro",
      },
      customCss: ["./src/styles/global.css"],
      lastUpdated: true,
      social: [
        { icon: "github", label: "GitHub", href: "https://github.com/oncehub" },
      ],
      sidebar: [...onceHubSidebar, ...scheduleOnceSidebar],
      head: [
        {
          tag: 'script',
          attrs: {
            src: 'https://bugdrop.neonwatty.workers.dev/widget.js',
            'data-repo': 'scheduleonce/help-center',
            defer: true,
          },
        },
      ],
      plugins: [
        starlightLinksValidator({
          failOnError: false,
        }),
        starlightPageActions({
          actions: {
            chatgpt: true,
            claude: true,
            markdown: true,
          },
          share: false,
        }),
        starlightLlmsTxt({
          projectName: "OnceHub Help Center",
        }),
      ],
    }),
  ],

  vite: {
    plugins: [tailwindcss()],
    server: {
      allowedHosts: [".trycloudflare.com"],
    },
  },
});
